// Minimal black-box reimplementation of the pieces of Python's `schedule`
// library exercised by test4.py: schedule.every().monday.at(timeStr).

import { ScheduleValueError } from './pyerrors.mjs';

export class Job {
  constructor(interval) {
    this.interval = interval;
    this.unit = null;      // 'weeks' once a weekday is selected
    this.startDay = null;  // e.g. 'monday'
    this.atTime = null;
    this.jobFunc = null;   // set by .do(), never called here
  }

  // schedule.every().monday
  get monday() {
    this.startDay = 'monday';
    this.unit = 'weeks';
    return this;
  }

  at(timeStr) {
    // start_day is set, so the daily time format rules apply.
    if (!/^[0-2]\d:[0-5]\d(:[0-5]\d)?$/.test(timeStr)) {
      // schedule/__init__.py, line 514
      throw new ScheduleValueError(
        'Invalid time format for a daily job (valid format is HH:MM(:SS)?)'
      );
    }
    const [hourStr] = timeStr.split(':');
    const hour = parseInt(hourStr, 10);
    if (hour < 0 || hour > 23) {
      // schedule/__init__.py, line 547 (the literal "{}" is a bug in the
      // original library and is reproduced verbatim)
      throw new ScheduleValueError(
        'Invalid number of hours ({} is not between 0 and 23)'
      );
    }
    this.atTime = timeStr;
    return this;
  }

  // Matches Python's Job.__repr__ for this configuration.
  toString() {
    return `Job(interval=${this.interval}, unit=${this.unit}, do=None, args=(), kwargs={})`;
  }
}

export function every() {
  return new Job(1);
}

// Minimal emulation of Python's argparse for the exact option set of test4.py:
// three required long string options plus the automatic -h/--help.

import { basename } from 'node:path';

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

class ArgparseExit extends Error {
  constructor(code) {
    super('argparse exit');
    this.code = code;
  }
}

export class ArgumentParser {
  constructor() {
    // argparse derives prog from os.path.basename(sys.argv[0])
    this.prog = basename(process.argv[1] || 'test4.mjs');
    this.options = [
      { names: ['-h', '--help'], metavar: null, required: false, help: 'show this help message and exit', isHelp: true },
    ];
  }

  add_argument(name, { required = false } = {}) {
    const dest = name.replace(/^--/, '');
    this.options.push({ names: [name], dest, metavar: dest.toUpperCase(), required, help: null, isHelp: false });
  }

  _invocation(opt) {
    if (opt.isHelp) return opt.names.join(', ');
    return `${opt.names[0]} ${opt.metavar}`;
  }

  format_usage() {
    const parts = this.options.map((opt) => {
      const inv = this._invocation(opt);
      return opt.required ? inv : `[${inv}]`;
    });
    return `usage: ${this.prog} ${parts.join(' ')}`;
  }

  format_help() {
    const invocations = this.options.map((opt) => this._invocation(opt));
    // argparse: help column = max invocation length + 2 (indented by 2), capped
    const helpCol = Math.min(Math.max(...invocations.map((s) => s.length)) + 2, 24) + 2;
    const lines = [this.format_usage(), '', 'options:'];
    this.options.forEach((opt, i) => {
      const head = '  ' + invocations[i];
      lines.push(opt.help ? head.padEnd(helpCol) + opt.help : head);
    });
    return lines.join('\n') + '\n';
  }

  error(message) {
    process.stderr.write(this.format_usage() + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    throw new ArgparseExit(2);
  }

  _resolveLong(name) {
    const all = this.options.flatMap((opt) => opt.names.filter((n) => n.startsWith('--')).map((n) => [n, opt]));
    const exact = all.find(([n]) => n === name);
    if (exact) return exact[1];
    const matches = all.filter(([n]) => n.startsWith(name));
    const uniqueOpts = [...new Set(matches.map(([, opt]) => opt))];
    if (uniqueOpts.length === 1) return uniqueOpts[0];
    if (uniqueOpts.length > 1) {
      this.error(`ambiguous option: ${name} could match ${matches.map(([n]) => n).join(', ')}`);
    }
    return null;
  }

  _looksLikeOption(token) {
    if (!token.startsWith('-') || token === '-') return false;
    if (NEGATIVE_NUMBER.test(token)) return false;
    if (token.includes(' ')) return false;
    return true;
  }

  parse_args(argv = process.argv.slice(2)) {
    try {
      return this._parse(argv);
    } catch (e) {
      if (e instanceof ArgparseExit) process.exit(e.code);
      throw e;
    }
  }

  _parse(argv) {
    const values = {};
    const extras = [];
    let seenDashDash = false;

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];

      if (seenDashDash) {
        extras.push(token);
        continue;
      }
      if (token === '--') {
        seenDashDash = true;
        continue;
      }

      if (token.startsWith('--')) {
        const eq = token.indexOf('=');
        const name = eq === -1 ? token : token.slice(0, eq);
        const explicitValue = eq === -1 ? null : token.slice(eq + 1);
        const opt = this._resolveLong(name);
        if (!opt) {
          extras.push(token);
          continue;
        }
        if (opt.isHelp) {
          process.stdout.write(this.format_help());
          throw new ArgparseExit(0);
        }
        if (explicitValue !== null) {
          values[opt.dest] = explicitValue;
          continue;
        }
        const next = argv[i + 1];
        if (next === undefined || this._looksLikeOption(next)) {
          this.error(`argument ${opt.names[0]}: expected one argument`);
        }
        values[opt.dest] = next;
        i++;
        continue;
