      if (token.startsWith('-') && token !== '-' && !NEGATIVE_NUMBER.test(token)) {
        const opt = this.options.find((o) => o.names.includes(token));
        if (opt && opt.isHelp) {
          process.stdout.write(this.format_help());
          throw new ArgparseExit(0);
        }
        extras.push(token);
        continue;
