    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.map((o) => o.names[0]).join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return values;
  }
